import functools
import time
from typing import Callable, TypeVar, ParamSpec

P = ParamSpec('P')
T = TypeVar('T')

# Basic decorator with @wraps
def log_calls(func: Callable[P, T]) -> Callable[P, T]:
    @functools.wraps(func)   # copies __name__, __doc__, etc.
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> T:
        print(f'Calling {func.__name__}')
        result = func(*args, **kwargs)
        print(f'{func.__name__} returned {result}')
        return result
    return wrapper

@log_calls
def add(a: int, b: int) -> int:
    """Add two numbers."""
    return a + b

print(add.__name__)   # 'add' (not 'wrapper') — because of @wraps
print(add.__doc__)    # 'Add two numbers.'

# Parametrized decorator — factory returns decorator
def retry(max_attempts: int = 3, exceptions: tuple = (Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    if attempt == max_attempts:
                        raise
                    print(f'Attempt {attempt} failed: {e}, retrying...')
        return wrapper
    return decorator

